await story('P2-A8-09-natural-clock-start',async()=>{
 const e=await welcome('expiry',cases[0],'P2-expiry-welcome');await e.p.fill('#quickFleetLabel','Pass2 natural expiry');const rr=e.p.waitForResponse(r=>new URL(r.url()).pathname==='/hub/v1/quick-pairing'&&r.request().method()==='POST');await e.p.locator('[data-quick-pairing] form button[type=submit]').click();const offer=await(await rr).json();const code=(await e.p.locator('[data-quick-pairing] .hub-fp-groups').first().innerText()).trim();
 const eh=join(scratch,'expiry-only-member');mkdirSync(eh,{mode:0o700});const ep=createHubMemberPairingApi({home:eh,enabled:()=>true});extraPairings.push(ep);fx.fm.attachHubMemberPairing(ep);const l=await hostPage(cases[0]);await l.p.fill('#hubAddress',memberOrigin);await l.p.fill('#hubCode',code);await l.p.locator('#hub-connect form button[type=submit]').click();await l.p.locator('.hub-local-confirm').waitFor();await e.p.getByRole('button',{name:'They match',exact:true}).waitFor();
 check('Hub address label matches actual local field',await e.p.getByText('Hub address',{exact:true}).count()===1);check('code acceptance leaves local step current',await e.p.locator('[data-quick-pairing] .hub-steps>li').first().getAttribute('class')==='now');const a=(await e.p.locator('[data-quick-pairing] .hub-fp-groups').last().innerText()).replace(/\s/g,''),b=(await l.p.locator('.hub-pending .hub-fp-groups').innerText()).replace(/\s/g,'');check('expiry exact fingerprint',a===b&&a.length===32);await shot(e.p,'P2-A8-09-code-accepted-local-not-done');
 await e.p.getByRole('button',{name:'They match',exact:true}).click();await pauseMs(300);check('Hub confirmation alone leaves local step current',await e.p.locator('[data-quick-pairing] .hub-steps>li').first().getAttribute('class')==='now');check('no false Connected without local proof',await e.p.getByText('Connected',{exact:true}).count()===0);await shot(e.p,'P2-A8-09-hub-confirmed-local-not-done');await l.ctx.close();globalThis.p2Expiry={e,ep,code,expiresAt:offer.expiresAt};receipt.naturalExpiry={started:Date.now(),expiresAt:offer.expiresAt};console.log('NATURAL_EXPIRY_DEADLINE',new Date(offer.expiresAt).toISOString());
});
await story('P2-A8-05-06-full-matrix',async()=>{for(const [login,flags,id]of[['ungranted',['false','true'],'05'],['owner',['false','false'],'06']])for(const c of matrix('full')){const start=receipt.network.length;const o=await context(c);try{await signIn(o.p,login);await o.p.locator('[data-welcome=nothing-shared]').waitFor();check(`${id}/${caseName(c)} empty hint and actual flags`,JSON.stringify(await o.p.locator('.hub-welcome-card').evaluateAll(r=>r.map(x=>x.getAttribute('aria-disabled'))))===JSON.stringify(flags));await shot(o.p,`P2-A8-${id}-${caseName(c)}`);await geometry(o.p,id+'/'+caseName(c));check('ordinary welcome has no429',!receipt.network.slice(start).some(r=>r.status===429));}finally{await o.ctx.close();}}});
await story('P2-regression-none-HELD',async()=>{for(const c of matrix('quick')){const n=await context(c);try{await signIn(n.p,'outsider');await n.p.locator('[data-welcome=no-actions]').waitFor();check('none both actions disabled',JSON.stringify(await n.p.locator('.hub-welcome-card').evaluateAll(r=>r.map(x=>x.getAttribute('aria-disabled'))))==='["true","true"]');await shot(n.p,'P2-none-'+caseName(c));}finally{await n.ctx.close();}}
 peer.state.mode='missing';const o=await context(cases[0]);try{await signIn(o.p,'owner');await o.p.locator('[data-welcome=unknown]').waitFor();check('unknown no actions',JSON.stringify(await o.p.locator('.hub-welcome-card').evaluateAll(r=>r.map(x=>x.getAttribute('aria-disabled'))))==='["true","true"]');await shot(o.p,'P2-held');peer.state.mode='ok';await o.p.locator('[data-welcome=unknown] button').click();await o.p.locator('[data-entry=connect][aria-disabled=false]').waitFor();check('HELD Retry recovers without Resume',true);}finally{peer.state.mode='ok';await o.ctx.close();}
});
